package ai.interviewiq.api.controller; import ai.interviewiq.api.dto.AuthDtos.*; import ai.interviewiq.api.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { final AuthService s; public AuthController(AuthService a){s=a;} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public AuthResponse register(@Valid @RequestBody RegisterRequest r){return s.register(r);} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);} @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) public void logout(){} }
